import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  collides,
  step,
  createState,
  ballSpeed,
  scoreForBrick,
} from '../game/neon.js';

// --- Aujourd'hui : la résolution brique de frame() (neon.js) ---------------
// Overlap -> brique tuée + score. AUCUNE déviation de la balle.
function todayResolve(state) {
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    if (collides(state.ball, brick)) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }
  }
}
function todayAdvance(state, dt) {
  step(state, dt);
  todayResolve(state);
}

// --- Corrections naïves -----------------------------------------------------

// D1/D3 : on inverse la vitesse, on ne repositionne pas.
function naiveFlipOnly(state, dt) {
  step(state, dt);
  for (const brick of state.bricks) {
    if (!brick.alive || !collides(state.ball, brick)) continue;
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
    state.ball.vy = -state.ball.vy;
  }
}

// D5a : on inverse toujours l'axe vertical (mauvais axe sur un choc de flanc).
function naiveAlwaysVy(state, dt) {
  step(state, dt);
  for (const brick of state.bricks) {
    if (!brick.alive || !collides(state.ball, brick)) continue;
    brick.alive = false;
    state.ball.vy = -state.ball.vy;
  }
}

// D5b : plus petite pénétration, sans le cas du coin (égalité -> axe vertical).
function naiveSingleAxis(state, dt) {
  step(state, dt);
  for (const brick of state.bricks) {
    if (!brick.alive || !collides(state.ball, brick)) continue;
    brick.alive = false;
    const dx = Math.min(
      state.ball.x + state.ball.r - brick.x,
      brick.x + brick.w - (state.ball.x - state.ball.r),
    );
    const dy = Math.min(
      state.ball.y + state.ball.r - brick.y,
      brick.y + brick.h - (state.ball.y - state.ball.r),
    );
    if (dx <= dy) state.ball.vx = -state.ball.vx;
    else state.ball.vy = -state.ball.vy;
  }
}

// D4 : résolution brique par brique (avec repositionnement) -> la couture
// inverse deux fois le même axe. D2 : sans sous-pas -> pas assez fin.
function naivePerBrick(state, dt) {
  step(state, dt);
  for (const brick of state.bricks) {
    if (!brick.alive || !collides(state.ball, brick)) continue;
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
    const dxL = state.ball.x + state.ball.r - brick.x;
    const dxR = brick.x + brick.w - (state.ball.x - state.ball.r);
    const dyT = state.ball.y + state.ball.r - brick.y;
    const dyB = brick.y + brick.h - (state.ball.y - state.ball.r);
    if (Math.min(dxL, dxR) < Math.min(dyT, dyB)) {
      state.ball.vx = -state.ball.vx;
      state.ball.x = dxL < dxR ? brick.x - state.ball.r : brick.x + brick.w + state.ball.r;
    } else {
      state.ball.vy = -state.ball.vy;
      state.ball.y = dyT < dyB ? brick.y - state.ball.r : brick.y + brick.h + state.ball.r;
    }
  }
}

// --- Helpers de scénario ----------------------------------------------------

const brickByRC = (state, row, col) =>
  state.bricks.find((b) => b.row === row && b.col === col);

