export function resolveBricks(state, prevX = state.ball.x, prevY = state.ball.y) {
  const { ball } = state;
  const hits = state.bricks.filter((b) => b.alive && collides(ball, b));
  if (hits.length === 0) return false;

  // Destroy + score (each brick counted once via `alive`).
  for (const brick of hits) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }

  // One bounce for the whole pass: collect the candidate faces from the
  // position the ball had BEFORE the step (swept-style), break ties by
  // penetration, then apply a single flip per axis.
  let flipX = false, flipY = false;
  let pushX = null, pushY = null;

  const consider = (axis, target) => {
    if (axis === 'x') { flipX = true; pushX = target; }
    else { flipY = true; pushY = target; }
  };

  for (const b of hits) {
    const penLeft = ball.x + ball.r - b.x;
    const penRight = b.x + b.w - (ball.x - ball.r);
    const penTop = ball.y + ball.r - b.y;
    const penBottom = b.y + b.h - (ball.y - ball.r);
    const dx = Math.min(penLeft, penRight);
    const dy = Math.min(penTop, penBottom);
    const wasAbove = prevY + ball.r <= b.y;
    const wasBelow = prevY - ball.r >= b.y + b.h;
    const wasLeft = prevX + ball.r <= b.x;
    const wasRight = prevX - ball.r >= b.x + b.w;

    if (wasAbove && wasLeft) {
      if (dx === dy) { consider('x', b.x - ball.r); consider('y', b.y - ball.r); } // coin
      else if (dx < dy) consider('x', penLeft < penRight ? b.x - ball.r : b.x + b.w + ball.r);
      else consider('y', b.y - ball.r);
    } else if (wasAbove && wasRight) { ... symmetric ... }
    else if (wasBelow && wasLeft) { ... }
    else if (wasBelow && wasRight) { ... }
    else if (wasAbove) consider('y', b.y - ball.r);
    else if (wasBelow) consider('y', b.y + b.h + ball.r);
    else if (wasLeft) consider('x', b.x - ball.r);
    else if (wasRight) consider('x', b.x + b.w + ball.r);
    else {
      // Dégénéré : déjà à l'intérieur avant le pas -> plus petite pénétration.
      if (dx <= dy) consider('x', penLeft < penRight ? b.x - ball.r : b.x + b.w + ball.r);
      else consider('y', penTop < penBottom ? b.y - ball.r : b.y + b.h + ball.r);
    }
  }

