export function advance(state, dt) {
  const speed = Math.hypot(state.ball.vx, state.ball.vy);
  const maxStep = 33; // strictly less than BRICK_H + 2*BALL_R (34)
  const n = Math.max(1, Math.ceil((speed * dt) / maxStep));
