// Resolves the ball against every live brick it overlaps: destroys the
// bricks it touches, awards score/combo, then applies a single bounce whose
// face is the axis of smallest penetration (corner: both axes).
export function resolveBricks(state, prevX = state.ball.x, prevY = state.ball.y) {
  const { ball } = state;
  const hits = state.bricks.filter((b) => b.alive && collides(ball, b));
  if (hits.length === 0) return false;

  // Destroy + score every touched brick (counted once via `alive`).
  for (const brick of hits) {
    brick.alive = false;
    state.combo += 1;
