// --- Brick collision (pure, tested) ----------------------------------------

// Resolves the ball against every live brick it overlaps. Destroys each
// touched brick (counted once via `alive`), awards score/combo, then applies
// a bounce: the crossed face is the axis of smallest penetration, with the
// ball pushed back out so it only touches the brick (never overlaps it).
// Returns `true` if at least one brick was hit.
//
// `prevX`/`prevY` (position BEFORE the movement step) are accepted for the
// swept-style face detection: a ball that was entirely above the brick before
// the step crossed the top face, even if the final overlap is deep.
export function resolveBricks(state, prevX = state.ball.x, prevY = state.ball.y) {
  const { ball } = state;
  const hits = state.bricks.filter((b) => b.alive && collides(ball, b));
  if (hits.length === 0) return false;

  for (const brick of hits) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }

  for (const b of hits) {
    const penLeft = ball.x + ball.r - b.x;
    const penRight = b.x + b.w - (ball.x - ball.r);
    const penTop = ball.y + ball.r - b.y;
    const penBottom = b.y + b.h - (ball.y - ball.r);
    const dx = Math.min(penLeft, penRight);
    const dy = Math.min(penTop, penBottom);
    const fromLeft = penLeft < penRight;
    const fromTop = penTop < penBottom;

    if (dx < dy) {
      // Side face: horizontal bounce, pushed out to the least-penetrated side.
      ball.x = fromLeft ? b.x - ball.r : b.x + b.w + ball.r;
      ball.vx = ball.x < b.x ? -Math.abs(ball.vx) : Math.abs(ball.vx);
    } else {
      // Top/bottom face: vertical bounce.
      ball.y = fromTop ? b.y - ball.r : b.y + b.h + ball.r;
      ball.vy = ball.y < b.y ? -Math.abs(ball.vy) : Math.abs(ball.vy);
    }
  }
  return true;
}

// Advances the ball by `dt`, moving it and resolving bricks AFTER the move
// (discrete pass). The movement will later be sub-stepped so that no brick
// can be crossed in a single jump (see to_fix.md D2).
export function advance(state, dt) {
  const prevX = state.ball.x;
  const prevY = state.ball.y;
  const lost = step(state, dt);
  resolveBricks(state, prevX, prevY);
  return lost;
}

