edits.newText:
// Advances the ball by `dt`, sub-stepping the movement so that no obstacle
// can be crossed in a single jump: the smallest distance the ball must not
// skip is BRICK_H + 2*BALL_R = 34 px (brick height + ball diameter), so each
// sub-step is kept strictly below that. Each sub-step moves the ball (walls,
// paddle) then resolves the bricks against the position the ball had BEFORE
// the move (swept-style face detection).
// Returns `true` if the ball is lost (exits through the bottom).
export function advance(state, dt) {
  const speed = Math.hypot(state.ball.vx, state.ball.vy);
  const maxStep = 33; // < BRICK_H + 2*BALL_R = 34
  const n = Math.max(1, Math.ceil((speed * dt) / maxStep));
  let lost = false;
  for (let i = 0; i < n; i++) {
    const prevX = state.ball.x;
    const prevY = state.ball.y;
    lost = step(state, dt / n) || lost;
    resolveBricks(state, prevX, prevY);
  }
  return lost;
}

