// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Does NOT handle bricks: that responsibility lives
// in advance()/resolveBricks() below.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    // The rebound angle depends on where the paddle was hit.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

// --- Brick collision (pure, tested) ----------------------------------------

// Resolves the ball against every live brick it overlaps. Destroys each
// touched brick (counted once via `alive`), awards score/combo, then applies
// a bounce: the crossed face is the axis of smallest penetration, with the
// ball pushed back out so it only touches the brick (never overlaps it).
// Returns `true` if at least one brick was hit.
//
// `prevX`/`prevY` (position BEFORE the movement step) are accepted for the
// swept-style face detection: a ball that was entirely above the brick before
// the step crossed the top face, even if the final overlap is deep.
export function resolveBricks(state, prevX = state.ball.x, prevY = state.ball.y) {
  const { ball } = state;
  const hits = state.bricks.filter((b) => b.alive && collides(ball, b));
  if (hits.length === 0) return false;

  for (const brick of hits) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }

  // One bounce per axis for the whole pass. Decisions are computed against
  // the ORIGINAL overlap and applied afterwards, so resolving one brick can
  // never disturb the face test of the next one (two adjacent bricks are
  // often touched at once across an 8 px grid seam).
  const actions = [];
  for (const b of hits) {
    const penLeft = ball.x + ball.r - b.x;
    const penRight = b.x + b.w - (ball.x - ball.r);
    const penTop = ball.y + ball.r - b.y;
    const penBottom = b.y + b.h - (ball.y - ball.r);
    const dx = Math.min(penLeft, penRight);
    const dy = Math.min(penTop, penBottom);
    const fromLeft = penLeft < penRight;
    const fromTop = penTop < penBottom;
    const wasAbove = prevY + ball.r <= b.y;
    const wasBelow = prevY - ball.r >= b.y + b.h;
    const wasLeft = prevX + ball.r <= b.x;
    const wasRight = prevX - ball.r >= b.x + b.w;

    // Corner: the ball came from two adjacent sides and the penetrations are
    // equal — both axes flip and the ball is pushed out along both.
    const corner =
      ((wasAbove && wasLeft) || (wasAbove && wasRight) ||
       (wasBelow && wasLeft) || (wasBelow && wasRight)) &&
      dx === dy;

    if (corner) {
      actions.push({
        x: fromLeft ? b.x - ball.r : b.x + b.w + ball.r,
        y: fromTop ? b.y - ball.r : b.y + b.h + ball.r,
        vx: (fromLeft ? b.x - ball.r : b.x + b.w + ball.r) < b.x ? -Math.abs(ball.vx) : Math.abs(ball.vx),
        vy: (fromTop ? b.y - ball.r : b.y + b.h + ball.r) < b.y ? -Math.abs(ball.vy) : Math.abs(ball.vy),
      });
    } else if (wasAbove) {
      // Crossed the top face: bounce up, ball pushed above the brick.
      actions.push({ y: b.y - ball.r, vy: -Math.abs(ball.vy) });
    } else if (wasBelow) {
      actions.push({ y: b.y + b.h + ball.r, vy: Math.abs(ball.vy) });
    } else if (wasLeft) {
      actions.push({ x: b.x - ball.r, vx: -Math.abs(ball.vx) });
    } else if (wasRight) {
      actions.push({ x: b.x + b.w + ball.r, vx: Math.abs(ball.vx) });
    } else {
      // Degenerate: the ball was already inside the brick before the step (a
      // leftover of a push-out that brushed a neighbouring brick). Exit in
      // the direction the ball is moving so it keeps going instead of
      // oscillating between two rows.
      if (Math.abs(ball.vx) >= Math.abs(ball.vy)) {
        const x = ball.vx >= 0 ? b.x + b.w + ball.r : b.x - ball.r;
        actions.push({ x, vx: ball.vx >= 0 ? Math.abs(ball.vx) : -Math.abs(ball.vx) });
      } else {
        const y = ball.vy >= 0 ? b.y + b.h + ball.r : b.y - ball.r;
        actions.push({ y, vy: ball.vy >= 0 ? Math.abs(ball.vy) : -Math.abs(ball.vy) });
      }
    }
  }

  for (const a of actions) {
    if (a.x !== undefined) ball.x = a.x;
    if (a.y !== undefined) ball.y = a.y;
    if (a.vx !== undefined) ball.vx = a.vx;
    if (a.vy !== undefined) ball.vy = a.vy;
  }
  return true;
}

// Advances the ball by `dt`, sub-stepping the movement so that no obstacle
// can be crossed in a single jump: the smallest distance the ball must not
// skip is BRICK_H + 2*BALL_R = 34 px (brick height + ball diameter), so each
// sub-step is kept strictly below that. Each sub-step moves the ball (walls,
// paddle) then resolves the bricks against the position the ball had BEFORE
// the move (swept-style face detection).
// Returns `true` if the ball is lost (exits through the bottom).
export function advance(state, dt) {
  const speed = Math.hypot(state.ball.vx, state.ball.vy);
  const maxStep = 33; // < BRICK_H + 2*BALL_R = 34
